-- composition of rule kernels ExistsToJoin x Transitive (sqlite), template product
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 20) SELECT CAST('c4ca4238a0b923820dcc509a6f75849b' AS TEXT) AS c0, CAST('{"k": 1}' AS TEXT) AS c1 FROM rc AS a1 WHERE (EXISTS (SELECT CAST(5e-324 AS REAL) AS c0, '{"k": 2, "a": [0]}' AS c1 FROM tp AS a2))) AS ka CROSS JOIN (SELECT a2.c2 AS c0, a3.c1 AS c1, a1.c1 AS c2, 10 AS c3 FROM (ti AS a1 INNER JOIN (t1 AS a2 JOIN t0 AS a3 ON ((a2.c0 = a3.c0) AND FALSE)) ON (a1.c0 = a3.c0))) AS kb;
